select.if:
select SEQNO, creditMstId, null customerId, null customerName, null PFLSH, creditQuoteTypeValue, creditAmt, VDATE, MDATE, usedAmt, usedEnstustAmt, usedAmtTotal, remainAmt, '02' hasChildren, CONCAT(PFLSH, customerId) parentInfo, null childInfo from CET
parentCustomerId is not null AND creditQuoteRank = '01' AND CONCAT(PFLSH, customerId) = #{parentId}
union all
select SEQNO, creditMstId, customerId, null customerName, null PFLSH, creditQuoteTypeValue, creditAmt, VDATE, MDATE, usedAmt, usedEnstustAmt, usedAmtTotal, remainAmt, '01' hasChildren, #{parentId} parentInfo, null childInfo from CET left join SYS_DATADICT_LIST_LINK dll on dll.DICT_CODE = creditQuoteTypeCode and dll.ITEM_CODE = creditQuoteType
parentCustomerId is not null and (creditQuoteRank is null or creditQuoteRank != '01') and rtrim(concat(concat(CONCAT(PFLSH, customerId), dll.LINKED_DICT_CODE), dll.LINKED_ITEM_CODE)) = #{parentId}
